    // Helper class to simulate NodeIterator behavior
    private static class NodeIteratorStub implements NodeIterator {
        private final List<NodePointer> pointers;
        private int index = 0;

        NodeIteratorStub(NodePointer... pointers) {
            this.pointers = new ArrayList<>();
            for (NodePointer pointer : pointers) {
                this.pointers.add(pointer);
            }
        }

        @Override
        public NodePointer getNodePointer() {
            return index < pointers.size() ? pointers.get(index) : null;
        }

        @Override
        public int getPosition() {
            return index;
        }

        @Override
        public boolean setPosition(int position) {
            if (position >= 0 && position <= pointers.size()) {
                index = position;
                return position > 0 && position <= pointers.size();
            }
            return false;
        }
    }
