import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class LookupStaticMethodTests {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Test
    public void test_lookupStaticMethod_ExactMatch() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethod", 
            new Object[]{Integer.valueOf(5), "test"}
        );

        assertNotNull(method);
        assertEquals("staticMethod", method.getName());
        assertEquals(Integer.class, method.getParameterTypes()[0]);
        assertEquals(String.class, method.getParameterTypes()[1]);
    }

    @Test
    public void test_lookupStaticMethod_ExactMatchWithNullParameters() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodWithNullParam", 
            new Object[]{null, "test"}
        );

        assertNotNull(method);
        assertEquals("staticMethodWithNullParam", method.getName());
        assertEquals(Integer.class, method.getParameterTypes()[0]);
        assertEquals(String.class, method.getParameterTypes()[1]);
    }

    @Test
    public void test_lookupStaticMethod_NoParameters() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodNoParams", 
            new Object[]{}
        );

        assertNotNull(method);
        assertEquals("staticMethodNoParams", method.getName());
        assertEquals(0, method.getParameterTypes().length);
    }

    @Test
    public void test_lookupStaticMethod_NullParametersArray() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodNoParams", 
            null
        );

        assertNotNull(method);
        assertEquals("staticMethodNoParams", method.getName());
        assertEquals(0, method.getParameterTypes().length);
    }

    @Test
    public void test_lookupStaticMethod_TypeConversionMatch() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethod", 
            new Object[]{5, "test"}
        );

        assertNotNull(method);
        assertEquals("staticMethod", method.getName());
        assertEquals(Integer.class, method.getParameterTypes()[0]);
        assertEquals(String.class, method.getParameterTypes()[1]);
    }

    @Test
    public void test_lookupStaticMethod_MultipleMatchesThrowsException() {
        thrown.expect(JXPathException.class);

        MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "overloadedStaticMethod", 
            new Object[]{Integer.valueOf(5)}
        );
    }

    @Test
    public void test_lookupStaticMethod_NoMatchingMethod() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "nonExistentMethod", 
            new Object[]{1, 2, 3}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_EmptyName() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "", 
            new Object[]{}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_NullName() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            null, 
            new Object[]{}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_NonStaticMethodIgnored() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "instanceMethod", 
            new Object[]{}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_InheritedStaticMethod() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestSubClass.class, 
            "staticMethodNoParams", 
            new Object[]{}
        );

        assertNotNull(method);
        assertEquals("staticMethodNoParams", method.getName());
    }

    @Test
    public void test_lookupStaticMethod_PrivateStaticMethod() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "privateStaticMethod", 
            new Object[]{}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_ParameterCountMismatch() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethod", 
            new Object[]{5}
        );

        assertNull(method);
    }

    @Test
    public void test_lookupStaticMethod_WithListParameter() throws Exception {
        List<String> list = new ArrayList<>();
        list.add("test");

        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodWithList", 
            new Object[]{list}
        );

        assertNotNull(method);
        assertEquals("staticMethodWithList", method.getName());
        assertEquals(List.class, method.getParameterTypes()[0]);
    }

    @Test
    public void test_lookupStaticMethod_ExactPrimitiveMatch() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodWithPrimitive", 
            new Object[]{5}
        );

        assertNotNull(method);
        assertEquals("staticMethodWithPrimitive", method.getName());
        assertEquals(int.class, method.getParameterTypes()[0]);
    }

    @Test
    public void test_lookupStaticMethod_WrapperToPrimitiveConversion() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodWithPrimitive", 
            new Object[]{Integer.valueOf(10)}
        );

        assertNotNull(method);
        assertEquals("staticMethodWithPrimitive", method.getName());
        assertEquals(int.class, method.getParameterTypes()[0]);
    }

    @Test
    public void test_lookupStaticMethod_PrimitiveToWrapperConversion() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            TestClass.class, 
            "staticMethodWithWrapper", 
            new Object[]{5}
        );

        assertNotNull(method);
        assertEquals("staticMethodWithWrapper", method.getName());
        assertEquals(Integer.class, method.getParameterTypes()[0]);
    }

    @Test
    public void test_lookupStaticMethod_NullTargetClass() throws Exception {
        Method method = MethodLookupUtils.lookupStaticMethod(
            null, 
            "staticMethodNoParams", 
            new Object[]{}
        );

        assertNull(method);
    }

    // Test helper classes
    public static class TestClass {
        public static void staticMethod(Integer num, String str) {}
        public static void staticMethodWithNullParam(Integer num, String str) {}
        public static void staticMethodNoParams() {}
        public static void overloadedStaticMethod(Integer num) {}
        public static void overloadedStaticMethod(String str) {}
        public static void staticMethodWithList(List<String> list) {}
        public static void staticMethodWithPrimitive(int num) {}
        public static void staticMethodWithWrapper(Integer num) {}
        public void instanceMethod() {}
        private static void privateStaticMethod() {}
    }

    public static class TestSubClass extends TestClass {
        // Inherits static methods from parent
    }
}
